WITH valid AS (SELECT *, CASE WHEN firmware = '1.0.3' THEN 1 ELSE 0 END AS is_1_0_3, CASE WHEN temp_c >= 38 THEN 'High' WHEN temp_c >= 24.2 THEN 'Medium' ELSE 'Low' END AS temp_c_tier FROM device_readings WHERE reading_ts > TO_DATE('2025-09-01')), flagged AS (SELECT *, CASE WHEN LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts ASC, id ASC) IS NULL OR reading_ts > LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts ASC, id ASC) + INTERVAL 45 MINUTES THEN 1 ELSE 0 END AS new_group_flag FROM valid), sessionized AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY device_code ORDER BY reading_ts ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM flagged) SELECT DATE_TRUNC('HOUR', reading_ts) AS hour_window, CASE WHEN pressure >= 1029 THEN 'LARGE' ELSE 'SMALL' END AS pressure_tier, AVG(humidity) AS avg_humidity, ROUND(SUM(status_bits) / NULLIF(COUNT(CASE WHEN device_code = 'DV-04' THEN 1 END), 0), 2) AS status_bits_per_dv_04, SUM(CASE WHEN device_code = 'DV-04' THEN temp_c ELSE 0 END) AS dv_04_temp_c, SORT_ARRAY(COLLECT_SET(device_code)) AS device_code_list, APPROX_PERCENTILE(status_bits, ARRAY(0.25, 0.5, 0.75)) AS status_bits_quartiles, COUNT(*) AS num_rows FROM sessionized GROUP BY hour_window, pressure_tier HAVING AVG(humidity) < 1000000;
